            else:
                # Show first element if list, or first key if dict
                first = next(iter(data.values()), None)
                if isinstance(first, list):
                    print(f"  First element: {first[:3]}...")
                elif isinstance(first, dict):
                    print(f"  First key/values: {list(first.items())[:3]}")
                else:
                    print(f"  Raw value: {first}")
        elif isinstance(data, list):
            if data:
