                if isinstance(first, dict):
                    print(f"  First element keys: {list(first.keys())}")
                    if 'input' in first:
                        print(f"  First.input: {first['input'][:2]}...")
                    if 'output' in first:
                        print(f"  First.output: {first['output'][:2]}...")
                else:
                    print(f"  First element: {first[:3]}...")
            else:
                print(f"  Empty list")
    except Exception as e:
        print(f"{fname}: Error - {e}")

